package net.minecraft.world.level; public class ChunkPos { public final int x,z; public ChunkPos(int x,int z){this.x=x;this.z=z;} public ChunkPos(long l){this((int)l,(int)(l>>>32));} public long toLong(){return asLong(x,z);} public static long asLong(int x,int z){return (long)x & 4294967295L | ((long)z & 4294967295L) << 32;} public boolean equals(Object o){return o instanceof ChunkPos c && c.x==x && c.z==z;} public int hashCode(){return 31*x+z;} public String toString(){return "["+x+", "+z+"]";} }
